using System;using System.IO;using System.Linq;using System.Collections.Generic;using UnityEngine;using UnityEditor;using UnityEditor.SceneManagement;using UnityEngine.SceneManagement;using UnityEngine.Rendering.Universal;using Newtonsoft.Json;
public static class ProtocolDesk {
 static string R=>Path.GetFullPath(Path.Combine(Application.dataPath,"../../.."));static string H=>R+"/SourceAssets/B4_DeskAndCollision/";static string O=>R+"/Docs/Review/2026-11-09_FloorSurfaceWear/";const string P="Assets/Afrer_Seconds/05.Model/Props/B4/";
 static Transform[] Targets()=>SceneManager.GetActiveScene().GetRootGameObjects().SelectMany(g=>g.GetComponentsInChildren<Transform>()).Where(t=>t.name.Contains("_ProtocolTable_")&&t.GetComponent<MeshFilter>()).ToArray();
 public static void Shot(string n,Vector3 pos,Vector3 to,float fov=60){var g=new GameObject("DetailReviewCamera"){hideFlags=HideFlags.HideAndDontSave};var c=g.AddComponent<Camera>();c.transform.position=pos;c.transform.LookAt(to);c.fieldOfView=fov;c.nearClipPlane=.04f;c.farClipPlane=250;c.useOcclusionCulling=false;c.GetUniversalAdditionalCameraData().renderPostProcessing=false;var rt=new RenderTexture(1440,1000,24){antiAliasing=4};var prev=RenderTexture.active;Texture2D tex=null;try{c.targetTexture=rt;c.Render();RenderTexture.active=rt;tex=new Texture2D(1440,1000,TextureFormat.RGB24,false);tex.ReadPixels(new Rect(0,0,1440,1000),0,0);tex.Apply();File.WriteAllBytes(O+n+".png",tex.EncodeToPNG());}finally{RenderTexture.active=prev;c.targetTexture=null;if(tex)UnityEngine.Object.DestroyImmediate(tex);UnityEngine.Object.DestroyImmediate(rt);UnityEngine.Object.DestroyImmediate(g);}}
 public static object CaptureAfter(){if(Application.isPlaying||SceneManager.GetActiveScene().isDirty)throw new Exception("Saved edit required");Capture("after");return new{images=5};}
 static void Capture(string phase){foreach(var t in Targets()){Shot(phase+"_"+t.name,t.TransformPoint(new Vector3(.6f,2.05f,2.25f)),t.TransformPoint(new Vector3(0,1.02f,-.06f)),64);if(t.name.Contains("_E02_"))Shot(phase+"_DeskRear",t.TransformPoint(new Vector3(-1.5f,1.65f,-1.7f)),t.TransformPoint(new Vector3(-.3f,1.02f,-.15f)),65);}}
 public static object Run(){var s=SceneManager.GetActiveScene();if(Application.isPlaying||s.isDirty||!s.path.EndsWith("Level_B4_Circular.unity"))throw new Exception("Saved B4 edit required");Capture("before");AssetDatabase.Refresh(ImportAssetOptions.ForceSynchronousImport);string path=P+"PD_ProtocolTable.fbx";var mi=(ModelImporter)AssetImporter.GetAtPath(path);mi.importAnimation=false;mi.importCameras=false;mi.importLights=false;mi.isReadable=true;mi.importNormals=ModelImporterNormals.Import;mi.importTangents=ModelImporterTangents.CalculateMikk;
 foreach(string dir in new[]{"Assets/Afrer_Seconds/05.Model/Environment/B4/Materials",P+"Materials"})foreach(var f in Directory.GetFiles(dir,"*.mat")){var m=AssetDatabase.LoadAssetAtPath<Material>(f.Replace('\\','/'));if(m&&(m.name.StartsWith("B4O_")||m.name.StartsWith("BX_Display")))mi.AddRemap(new AssetImporter.SourceAssetIdentifier(typeof(Material),m.name),m);}mi.SaveAndReimport();var prefab=AssetDatabase.LoadAssetAtPath<GameObject>(path);var src=prefab.GetComponentsInChildren<MeshFilter>().Single();var sr=src.GetComponent<MeshRenderer>();if(sr.sharedMaterials.Any(m=>!m))throw new Exception("Missing material");var changed=new List<object>();foreach(var t in Targets()){var mf=t.GetComponent<MeshFilter>();string old=AssetDatabase.GetAssetPath(mf.sharedMesh);mf.sharedMesh=src.sharedMesh;t.GetComponent<MeshRenderer>().sharedMaterials=sr.sharedMaterials;PrefabUtility.RecordPrefabInstancePropertyModifications(mf);PrefabUtility.RecordPrefabInstancePropertyModifications(t.GetComponent<MeshRenderer>());changed.Add(new{name=t.name,oldMesh=old,newMesh=path});}AssetDatabase.SaveAssets();EditorSceneManager.MarkSceneDirty(s);EditorSceneManager.SaveScene(s);File.WriteAllText(H+"desks.json",JsonConvert.SerializeObject(changed,Formatting.Indented));Capture("after");var target=Targets().Single(t=>t.name=="B4_E02_ProtocolTable_01");Selection.activeGameObject=target.gameObject;SceneView.lastActiveSceneView?.LookAt(target.position+Vector3.up,Quaternion.LookRotation(new Vector3(-.25f,-.45f,-1)),2.8f);return new{desks=changed,triangles=src.sharedMesh.triangles.Length/3,missing=sr.sharedMaterials.Count(m=>!m)};}
}
